The subspace of $U(N)$ invariant polynomials is denoted by
\begin{equation}
    \mathcal{H}_N = \qty{ \mathcal{F} (Z,W) \in \mathbb{C}[Z,W] \, \vert \, 
    \mathcal{F} (UZU^\dagger , UWU^\dagger) = \mathcal{F} (Z,W) \quad \forall U \in U(N)}.
\end{equation}
The space of invariants can be organised into subspaces of homogeneous bidegree, where $Z$ has degree $(1,0)$ and $W$ has degree $(0,1)$.
The subspaces of homogeneous degree $(m,n)$ are defined as
\begin{equation}
    \mathcal{H}_N(m,n) = \{ \mathcal{F}(Z,W) \in \mathcal{H}_N \, \vert \, \mathcal{F}(x Z, y W) = x^m y^n \mathcal{F}(Z,W) \, \forall x,y \in \mathbb{C}\},
\end{equation}
and give a decomposition
\begin{equation}
    \mathcal{H}_N = \bigoplus_{m,n \geq 0} \mathcal{H}_N(m,n).
\end{equation}

\label{ex: H_N(2,1)}
All elements in $\mathcal{H}_N(2,1)$ are linear combinations of 
\begin{equation}
\mathrm{tr}(ZZW), \quad \mathrm{tr}(ZZ)\mathrm{tr}(W), \quad \mathrm{tr}(ZW)\mathrm{tr}(Z), \quad \mathrm{tr}(Z)^2 \mathrm{tr}(W).
\end{equation}
In the stable regime $N \geq 3$, these elements form a basis. For $N < 3$ they are linearly dependent.

Let $S_L$ be the symmetric group on $L$ letters.
The symmetric group algebra $\mathbb{C}[S_L]$ is the complex vector space whose basis is $S_L$
\begin{equation}
\mathbb{C}[S_L]
= \Big\{ \sum_{g\in S_L} c_g \, g \, \Big| \, c_g \in\mathbb{C} \Big\}.
\end{equation}
It becomes a finite-dimensional associative algebra when the group multiplication is extended bilinearly
\begin{equation}
\Big( \sum_{g \in S_L} c_{g}  g \Big)
\Big( \sum_{g' \in S_L} c_{g'} {g'} \Big)
= \sum_{g, g' \in S_L} c_{g}  \, c_{g'} \, g g' .
\end{equation}

The product of elements $\sigma, \sigma' \in \mathbb{C}[S_3]$ given by
    \begin{equation}
        \sigma = (123) + (132), \quad \sigma' = (12) + (13)
    \end{equation}
    is given by
    \begin{equation}
        \sigma \sigma' = (123)(12) + (123)(13) + (132)(12) + (132)(13) = (12) + (13) + 2 \, (23).
    \end{equation}
We use the convention $(g_1g_2)(i)=g_2(g_1(i))$ following \cite{Padellaro:2024rld}.

The permutation centraliser algebra (PCA) at degree $(m,n)$ is the subspace of the group algebra made out of elements that commute with $S_m \times S_n$
\begin{equation}
{\mathcal A}(m,n)
=
\{\sigma \in \mathbb{C}[S_{m+n}] \, \vert  \, \gamma \sigma \gamma^{-1}=\sigma, \quad \forall \gamma \in S_m \times S_n \}.
\label{def:PCA}
\end{equation}

\label{def:trace map}
For $g\in S_{m+n}$\,, we define the multi-trace $U(N)$ invariant
\begin{equation}
\mathscr{O}^{(N)}_{m,n}(g) \equiv \sum_{i_1,\dots,i_{m+n}=1}^N
\prod_{p=1}^m Z_{i_p i_{g(p)}}
\prod_{q=m+1}^{m+n} W_{i_q i_{g(q)}} \,.
\label{eq:Og-definition}
\end{equation}
For a group-algebra element $\sigma=\sum_{g\in S_{m+n}}c_g(\sigma)g$, we linearly extend the above map,
\begin{equation}
\mathscr{O}^{(N)}_{m,n}(\sigma) \equiv
\sum_{g\in S_{m+n}}c_g(\sigma)\,\mathscr{O}^{(N)}_{m,n}(g) .
\label{eq:Osigma-definition}
\end{equation}
Since $\mathscr{O}^{(N)}_{m,n}(\sigma) = \mathscr{O}^{(N)}_{m,n}(h \sigma h^{-1})$ for any $h \in S_m \times S_n$\,, we obtain a map from permutation centraliser algebras to invariants
\begin{equation}
\mathscr{O}^{(N)}_{m,n}: {\mathcal A}(m,n) \rightarrow \mathcal{H}_N(m,n).
\end{equation}

Consider $\sigma = (13)(24) + (14)(23)$ with $m=n=2$, then
    \begin{equation}
        \mathscr{O}^{(N)}_{2,2}(\sigma)
        = \sum_{i_1,i_2,i_3,i_4=1}^N \Big( Z_{i_1 i_3}Z_{i_2 i_4} W_{i_3 i_1} W_{i_4 i_2} + Z_{i_1 i_4}Z_{i_2 i_3} W_{i_3 i_2} W_{i_4 i_1} \Big)
        = 2 \mathrm{tr}(ZW)\mathrm{tr}(ZW).
    \end{equation}

Let $\{ g_1,\dots, g_l\}$ be a complete set of representatives of $S_m \times S_n$ orbits of $S_{m+n}$.
For each representative $g_k$, define the following element in ${\mathcal A}(m,n)$
\begin{equation}
    P_{m,n}(g_k)=\sum_{h \in S_m \times S_n } hg_kh^{-1} \,.
\label{eq:orbit-sum}
\end{equation}
We extend $P_{m,n}$ linearly to $\mathbb{C}[S_{m+n}]$.
They form the orbit basis of ${\mathcal A}(m,n)$
\begin{equation}
{\mathcal A}(m,n)=
\operatorname{Span}_{\mathbb C}\left( P_{m,n}(g_1),\dots, P_{m,n}(g_l)\right).
\label{eq:orbit-basis}
\end{equation}

\label{def:orbit-basis inner prod}
Define the linear function $\delta: \mathbb{C} [S_{m+n}] \rightarrow \mathbb{C}$ by
\begin{equation}
    \delta(g) = \begin{cases}
        1, &\text{ if $g=\mathrm{id}$}\\
        0, &\text{ if $g\neq \mathrm{id}$}.
    \end{cases}
\end{equation}
A natural inner product on ${\mathcal A}(m,n)$ is given by
\begin{equation}
\langle \sigma, \sigma' \rangle = \delta(\sigma {\mathcal S}(\sigma'))
\label{eq: inner prod}
\end{equation}
where ${\mathcal S}$ is the involution
\begin{equation}
    \mathcal{S}\qty(\sum_{k=1}^l c_k P_{m,n}(g_k)) = \sum_{k=1}^l c_k^* P_{m,n}(g_k^{-1}).
\end{equation}
The orbit basis is orthogonal with respect to this inner product, which we call the orbit-basis inner product.

The centre of $\mathbb{C}[S_L]$ is the subspace of elements that commute with all of $\mathbb{C}[S_L]$
\begin{equation}
    \mathcal{Z} ( \mathbb{C}[S_L] ) = \{ \omega \in \mathbb{C}[S_L] \, \vert \, g \omega = \omega g \quad \forall g \in S_L \}.
\end{equation}
It is also equivalent to the permutation centraliser algebra ${\mathcal A}(L,0)$.

\label{def:left center}
Let $\omega \in \mathcal{Z}(\mathbb{C}[S_L])$ have an expansion
\begin{equation}
    \omega = \sum_{g \in S_L} c_g(\omega) g.
\end{equation}
The left action of $\omega$ on $\sigma \in {\mathcal A}(m,n)$ is given by
\begin{equation}
m^{\mathfrak{L}}: \mathcal{Z}(\mathbb{C}[S_{m+n}]) \otimes {\mathcal A}(m,n) \rightarrow {\mathcal A}(m,n) , \qquad
m^{\mathfrak{L}}[\omega ](\sigma) = \sum_{g \in S_L} c_g(\omega ) g \sigma.
\end{equation}

\label{def:finite-N basis}
A basis for ${\mathcal A}(m,n)$ is called SEP
if it simultaneously diagonalises the left action of the centre.
Such bases can always be labelled by an integer partition $R \vdash L$ and $a \in \{1,\dots, g(R)\}$, where $g(R)$ is defined in equation \eqref{eq: g(R)}.
For example, write
\begin{equation}
    \mathcal{Q}^{R}_a = \sum_{k=1}^l \mathcal{Q}^{R}_a(g_k) P_{m,n}(g_k)
\label{cQRa expand}
\end{equation}
then the coefficients $\mathcal{Q}^{R}_a(g_k)$ are constrained by demanding
\begin{equation}
    m^{\mathfrak{L}}[ \omega ](\mathcal{Q}^R_a) = \frac{\chi^R(\omega )}{d_R} \mathcal{Q}^R_a.
\label{left-center Q^R_a}
\end{equation}
Here $\chi^R (\sigma)$ is the $S_L$ character for $\sigma \in \mathbb{C}[S_L]$, $d_R$ is the dimension of the irreducible representation of $S_L$ labelled by $R$, and $\frac{\chi^R(\omega )}{d_R}$ is called a central character.

The SEP bases for $L=m$ are (proportional to) central projectors. For example, at $L=3$ we have
    \begin{equation}
        {\mathcal Q}^{[3]} \propto \sum_{g \in S_3} g, \quad {\mathcal Q}^{[2,1]} \propto 2\, \mathrm{id} - (123) - (132), \quad {\mathcal Q}^{[1,1,1]} \propto \sum_{g \in S_3} \mathrm{sgn}(g)  g.
    \end{equation}

\label{def:cAN}
Let ${\mathcal Q}^R_a$ be a SEP basis.
For each positive integer $N$, ${\mathcal A}(m,n)$ has a subspace
\begin{equation}
    {\mathcal A}_N(m,n) = \operatorname{Span}_\mathbb{C}({\mathcal Q}^{R}_a \, \vert \, R \vdash (m+n), \ell(R) \leq N, a \in \{1,\dots,g(R)\}) .
\end{equation}

\label{prop:UN inner}
    The $U(N)$ inner product on ${\mathcal A}(m,n)$ is defined as the pullback of the free two-point function of $\mathcal{N}=4$ SYM with $U(N)$ gauge group.
For $\sigma_1 , \sigma_2 \in {\mathcal A}(m,n)$ 
\begin{equation} 
\begin{aligned}
\langle \sigma_1,\sigma_2\rangle_{U(N)} &\equiv 
\left\langle \mathscr{O}^{(N)}_{m,n}(\sigma_1) \, \mathscr{O}^{(N)}_{m,n}(\sigma_2)^\dagger \right\rangle_{{\mathcal N}=4} ,
\\
\text{where } \mathscr{O}^{(N)}_{m,n}(g)^\dagger &= \sum_{i_1,\dots,i_L=1}^N
\prod_{p=1}^m Z^\dagger_{i_p i_{g^{-1}(p)}} \prod_{q=m+1}^L W^\dagger_{i_q i_{g^{-1} (q)}} \,,
\end{aligned}
\label{eq:UN-pullback} 
\end{equation}
and the free two-point function is computed from the elementary $U(N)$ Wick contractions
\begin{equation} 
\left\langle Z_{ij}Z^\dagger_{kl}\right\rangle_{{\mathcal N}=4}
=\left\langle W_{ij}W^\dagger_{kl}\right\rangle_{{\mathcal N}=4}
=\delta_{il}\delta_{jk}. 
\label{eq:UN-wick} 
\end{equation}

For the first claim, decompose an arbitrary element $\sigma\in{\mathcal A}(m,n)$ into its $R$-sector components in the SEP basis:
\begin{equation}
\sigma=\sum_R\sigma_R, \qquad \sigma_R=\sum_a\sigma_{R,a} \, {\mathcal Q}^R_a.
\end{equation}
Distinct $R$-sectors are orthogonal in the orbit-basis inner product, and $\Omega_N$ acts on each sector by the scalar $f^R$.
The $U(N)$ inner product in Definition \ref{prop:UN inner} therefore expresses the free two-point function as
\begin{equation}
    \left\langle \mathscr{O}^{(N)}_{m,n}(\sigma) \, \mathscr{O}^{(N)}_{m,n}(\sigma)^\dagger \right\rangle_{{\mathcal N}=4}
    = \langle \sigma,\sigma\rangle_{U(N)}
    = m!n! \sum_R f^R \langle \sigma_R,\sigma_R\rangle .
\label{eq:SEP-norm}
\end{equation}
The orbit-basis inner product is positive definite, so $\langle \sigma_R,\sigma_R\rangle>0$ whenever $\sigma_R\neq0$.
Since $f^R>0$ for $\ell(R)\leq N$ and $f^R=0$ otherwise, the right-hand side vanishes if and only if $\sigma_R=0$ for every $R$ with $\ell(R)\leq N$.
The free two-point function is positive definite on ${\mathcal H}_N(m,n)$, so the left-hand side vanishes if and only if $\sigma\in\ker(\mathscr{O}^{(N)}_{m,n})$.
Comparing these conditions proves \eqref{eq:radical-kernel}.
The same identity shows that the restriction of the $U(N)$ inner product to ${\mathcal A}_N(m,n)$ is positive definite.
For the second claim, the two summands in \eqref{eq:PCA-orth-decomp} are spanned by the $R$-sectors with $\ell(R)\leq N$ and $\ell(R)>N$, respectively.
They exhaust ${\mathcal A}(m,n)$ and are orthogonal in the orbit-basis inner product, proving the orthogonal decomposition.

The permutations-to-invariants map $\mathscr{O}^{(N)}_{m,n}: {\mathcal A}(m,n) \rightarrow {\mathcal H}_N(m,n)$ is a linear map between finite-dimensional vector spaces.
We use the result from linear algebra that says that the restricted map is an isomorphism to the image.
In the present case, this says that we have an isomorphism
\begin{equation}
    \hat \mathscr{O}^{(N)}_{m,n}: {\mathcal A}_N(m,n) \rightarrow \operatorname{im} \mathscr{O}^{(N)}_{m,n}
\end{equation}
Since $\mathscr{O}^{(N)}_{m,n}$ is surjective, $\operatorname{im} \mathscr{O}^{(N)}_{m,n}  = {\mathcal H}_N(m,n)$ and we get ${\mathcal A}_N(m,n) \cong {\mathcal H}_N(m,n)$.
In other words, the restricted permutations-to-invariants map is an isomorphism to the space of invariants.

\label{def: 1LPDO}
For $h \in S_L$, define the intermediate map
\begin{equation}
    \bar H^{(1)}_{\xi}(h) \equiv \sum_{\substack{i=1\\ i\ne h(i)}}^L
\left[ h - (i,h(i))\, h\,(i,h(i)) \right]
 +{\xi} \sum_{i=1}^L \sum_{\substack{j=1\\ h(j)\ne i\\ j\ne i}}^L
\left[ h\, (i,h(j)) - (i,j)\, h\,(i,h(j))\,(i,j) \right].
\label{eq:D1-orbit-basis}
\end{equation}
This map is covariant under conjugation as shown in \eqref{app:D1 SL covariance},
\begin{equation}
\bar H^{(1)}_{\xi}(\gamma h\gamma^{-1}) = \gamma\bar H^{(1)}_{\xi}(h)\gamma^{-1}, \qquad \gamma\in S_L.
\label{eq:H1-conjugation}
\end{equation}
Consequently, $P_{m,n}\circ\bar H^{(1)}_{\xi}$ is independent of the representative chosen within each $S_m\times S_n$ orbit.
In the orbit basis, with representatives $\{g_1,\dots,g_l\}$, define the one-loop permutation dilatation operator by
\begin{equation}
    \begin{aligned}
        & H^{(1)}_{\xi}: {\mathcal A}(m,n) \rightarrow {\mathcal A}(m,n) \\
        & H^{(1)}_{\xi}(P_{m,n}(g_k)) \equiv P_{m,n} \circ \bar H^{(1)}_{\xi}(g_k).
    \end{aligned}
\end{equation}
The first term of \eqref{eq:D1-orbit-basis} is the planar contribution, while the second term is the non-planar contribution and carries an explicit factor of ${\xi}$.
Writing the full composition explicitly gives
\begin{equation}
    \begin{aligned}
    & H^{(1)}_{\xi}(P_{m,n} (g_k))
    =
\sum_{\substack{i=1\\ i\ne g_k(i)}}^L
\left\{
P_{m,n} (g_k) - P_{m,n}\!\left((i,g_k(i))g_k(i,g_k(i))\right)
\right\}
\\
    &\quad\quad\quad\quad\quad\quad\quad\quad +{\xi}
\sum_{i=1}^L
\sum_{\substack{j=1\\ g_k(j)\ne i\\ j\ne i}}^L
\left\{
P_{m,n} \!\left(g_k(i,g_k(j))\right)
- P_{m,n} \!\left((i,j)g_k(i,g_k(j))(i,j)\right)
\right\}.
    \end{aligned}
\end{equation}

The direct calculation in Appendix \ref{app:induced action D1} gives
\begin{equation}
\mathfrak{D}_N^{(1)}\!\left(\mathscr{O}^{(N)}_{m,n}(g)\right) 
= \mathscr{O}^{(N)}_{m,n}\!\left( \bar H^{(1)}_{\xi} (g)\right) \Big|_{\xi=1/N} , \qquad g \in S_L\,, \quad \forall N \in \mathbb{N}
\label{eq:direct calc D1}
\end{equation}
where the right-hand side is given by \eqref{eq:D1-orbit-basis}.
Equation \eqref{eq:direct calc D1} is the pointwise identity for each $g \in S_L$.
By using the conjugation property of the permutations-to-invariants map,
\begin{equation}
\mathscr{O}^{(N)}_{m,n}\!\left(P_{m,n}(g)\right) = m!n!\,\mathscr{O}^{(N)}_{m,n}(g)
\end{equation}
and $\bar H^{(1)}_{\xi}$ in \eqref{eq:H1-conjugation}, we can rewrite \eqref{eq:direct calc D1} as the action on the orbit basis of ${\mathcal A}(m,n)$.

\label{cor:finite-N factorisation}
Let $( H_{\xi}^{(1)})_{ba}^{SR}$ be the matrix elements of the one-loop permutation dilatation operator in a SEP basis ${\mathcal Q}^R_a$.
It has block triangular structure at $\xi = 1/N$
\begin{equation}
    ( H_{\xi}^{(1)})_{ba}^{SR}\Big \vert_{\xi=\frac{1}{N}} = \begin{pmatrix}  \mathfrak{D}_N^{(1)} & 0 \\ H_{21}^{(1)} & H_{22}^{(1)} \end{pmatrix}, 
\end{equation}
where the first and second blocks correspond to ${\mathcal A}_N(m,n)$ and $\ker(\mathscr{O}^{(N)}_{m,n})$, respectively.
The zero block corresponds to $\ell(R)>N$ and $\ell(S)\leq N$.
The matrix in the top-left block is the operator $ \mathfrak{D}_N^{(1)}$ evaluated in the basis $O^R_a = \hat \mathscr{O}^{(N)}_{m,n}({\mathcal Q}^R_a)$.

We consider two cases.
    The first case is $R$ with $\ell(R) \leq N$ such that ${\mathcal Q}^R_a \in {\mathcal A}_N(m,n)$.
    Extracting coefficients of $O^S_b$ in \eqref{eq: Hside} and \eqref{eq: Dside}  gives the equalities
    \begin{equation}
        ( H_{\xi}^{(1)})_{ba}^{SR}\Big \vert_{\xi=\frac{1}{N}} = ( \mathfrak{D}_N^{(1)})_{ba}^{SR}, \qquad \forall R,S \vdash (m+n) \text{ s.t. } \ell(R) \leq N, \ell(S) \leq N.
    \end{equation}
    This is the upper-left block in the lemma statement.
    The second case is $\ell(R) > N$ such that ${\mathcal Q}^R_a \in \ker \mathscr{O}^{(N)}_{m,n}$.
    In this case, extracting the coefficient of \eqref{eq: Dside2} gives zero and therefore
    \begin{equation}
        ( H_{\xi}^{(1)})_{ba}^{SR}\Big \vert_{\xi=\frac{1}{N}} = 0 \qquad \forall R,S \vdash (m+n) \text{ s.t. } \ell(R) > N, \ell(S) \leq N.
    \end{equation}

\label{lemma:finite-N factorisation}
    Let $\mathscr{O}^{(N)}_{m,n}$ be the map that takes elements of ${\mathcal A}(m,n)$ to invariant polynomials in $\mathcal{H}_{N}(m,n)$ and let $\ker\mathscr{O}^{(N)}_{m,n}$  be the subspace of elements that are mapped to zero.
    The one-loop permutation dilatation operator $ H^{(1)}_{\xi}: {\mathcal A}(m,n) \rightarrow {\mathcal A}(m,n)$ leaves $\ker\mathscr{O}^{(N)}_{m,n}$ invariant for $\xi=\tfrac{1}{N}$.

\label{prop: unstable 1LPDO}
    The composite operator 
   \begin{equation}
       P^{{\mathcal A}_N(m,n)} \circ  H^{(1)}_\xi\Big\vert_{\xi = 1/N}: {\mathcal A}_N(m,n) \rightarrow {\mathcal A}_N(m,n)
   \end{equation}
   is equivalent to the one-loop dilatation operator:
   \begin{equation}
       \label{eq: unstable 1LPDO prf}
       P^{{\mathcal A}_N(m,n)} \circ  H^{(1)}_\xi \vert_{\xi=1/N} = (\hat \mathscr{O}^{(N)} _{m,n})^{-1} \circ \mathfrak{D}^{(1)}_N \circ \hat \mathscr{O}^{(N)}_{m,n} \, .
   \end{equation}

The restricted permutations-to-invariants map is an isomorphism and therefore has a unique inverse.
For consistency with the rest of this section, take a SEP basis ${\mathcal Q}^R_a$ with $\ell(R) \leq N$ for ${\mathcal A}_N(m,n)$ and $O^R_a = \hat \mathscr{O}^{(N)}_{m,n}({\mathcal Q}^R_a)$ a basis for ${\mathcal H}_N(m,n)$.
This gives
\begin{equation}
    (\hat \mathscr{O}^{(N)} _{m,n})^{-1}(O^R_a) = {\mathcal Q}^R_a \quad \text{and}  \quad 
    P^{{\mathcal A}_N(m,n)}({\mathcal Q}^R_a) = 
    \begin{cases}
        {\mathcal Q}^R_a, &\text{ if $\ell(R) \leq N$ }\\
        0, &\text{ if $\ell(R) > N$. }
    \end{cases}
\end{equation}
and the l.h.s. of \eqref{eq: unstable 1LPDO prf} equals
\begin{equation}
    \begin{aligned}
        P^{{\mathcal A}_N(m,n)} \circ  H^{(1)}_\xi({\mathcal Q}^R_a)\Big\vert_{\xi = 1/N}&= 
    \sum_{S\vdash m+n} \sum_{b = 1}^{g(S)}  ( H^{(1)}_\xi)_{ba}^{SR}\Big\vert_{\xi=1/N} P^{{\mathcal A}_N(m,n)}({\mathcal Q}^S_b) \\
    &=
    \sum_{\substack{S\vdash m+n \\ \ell(S) \leq N}} \sum_{b = 1}^{g(S)}  ( H^{(1)}_\xi)_{ba}^{SR}\Big\vert_{\xi=1/N} {\mathcal Q}^S_b
    \end{aligned}
\end{equation}
while the r.h.s. equals
\begin{equation}
    \begin{aligned}
        ((\hat \mathscr{O}^{(N)} _{m,n})^{-1} \circ \mathfrak{D}^{(1)}_N \circ \hat \mathscr{O}^{(N)}_{m,n})({\mathcal Q}^R_a) 
        &= 
        ((\hat \mathscr{O}^{(N)} _{m,n})^{-1} \circ \mathfrak{D}^{(1)}_N)(O^R_a) \\
        &= \sum_{\substack{S\vdash m+n \\ \ell(S) \leq N}} \sum_{b = 1}^{g(S)}  ( \mathfrak{D}^{(1)}_N)_{ba}^{SR} (\hat \mathscr{O}^{(N)} _{m,n})^{-1}(O^S_b) \\
        &= \sum_{\substack{S\vdash m+n \\ \ell(S) \leq N}} \sum_{b = 1}^{g(S)}  ( \mathfrak{D}^{(1)}_N)_{ba}^{SR} {\mathcal Q}^S_b.
    \end{aligned}
\end{equation}
From Lemma \ref{cor:finite-N factorisation} the matrix elements agree and the two sides are equal.
Lastly, since the equality holds for all basis elements it holds at the level of operators.

\label{prop: unstable 1LPDO-2}
For any $\sigma_a,\sigma_b\in{\mathcal A}_N(m,n)$, the operators in Corollary \ref{prop: unstable 1LPDO} satisfy the equation
\begin{equation}
\left.\left\langle \sigma_b,
P^{{\mathcal A}_N(m,n)}\circ  H_{\xi}^{(1)}(\sigma_a)
\right\rangle_{U(N)}\right|_{\xi=1/N}
=
\left\langle
\mathscr{O}^{(N)}_{m,n}(\sigma_b)\,
\left(\mathfrak{D}_N^{(1)}\mathscr{O}^{(N)}_{m,n}(\sigma_a)\right)^\dagger
\right\rangle_{{\mathcal N}=4}.
\label{eq:finite-N physical matching}
\end{equation}

The following intertwining relation holds
\begin{equation}
\left.\mathscr{O}^{(N)}_{m,n}\!\left( H_{\xi}^{(1)}(\sigma)\right)\right|_{\xi=1/N}=
\left.\mathscr{O}^{(N)}_{m,n}\!\left(P^{{\mathcal A}_N(m,n)}\circ H_{\xi}^{(1)}(\sigma)\right)\right|_{\xi=1/N}
= \mathfrak{D}_N^{(1)}\mathscr{O}^{(N)}_{m,n}(\sigma).
\label{eq:projected finite-N intertwining}
\end{equation}
Substituting \eqref{eq:projected finite-N intertwining} into the definition of the $U(N)$ inner product, Definition \ref{prop:UN inner}, gives \eqref{eq:finite-N physical matching}.

\label{def:substitution maps}
Using the identity \eqref{eq:traceless-variable}, we introduce two substitution maps.
The map $\Psi : \mathcal{H}_N \, \to \, \mathcal{H}'_N \otimes \mathbb{C}[z,w]$ is
\begin{equation}
{\Psi}[ \mathcal{F} ] (Z',W',z,w) \equiv \mathcal{F} (Z' + I z, W' + I w) \ \in \ \mathcal{H}'_N \otimes \mathbb{C}[z,w] 
\label{def:Psi map}
\end{equation}
and the map $\Phi : \mathcal{H}'_N \otimes \mathbb{C}[z,w] \, \to \, \mathcal{H}_N$ is
\begin{equation}
\begin{aligned}
{\Phi}[\mathcal{F}' \otimes f ] (Z, W) 
&\equiv (\mathcal{F}' \otimes f) \Big(Z - I \, \frac{\mathrm{tr}(Z)}{N}, W - I \, \frac{\mathrm{tr}(W)}{N} , \frac{\mathrm{tr}(Z)}{N}, \frac{\mathrm{tr}(W)}{N} \Big) 
\\[1mm]
&= 
\mathcal{F} ' \Big(Z - I \, \frac{\mathrm{tr}(Z)}{N}, W - I \, \frac{\mathrm{tr}(W)}{N} \Big) \, 
f \Big( \frac{\mathrm{tr}(Z)}{N}, \frac{\mathrm{tr}(W)}{N} \Big) 
\ \in \ \mathcal{H}_N
\end{aligned}
\label{def:Phi map}
\end{equation}
together with linear extension.

For instance, the invariant $\mathrm{tr}(ZW)$ satisfies
\begin{equation}
\Psi[\mathrm{tr}(ZW)] = \mathrm{tr}(Z'W') + Nzw , \qquad
\Phi[\mathrm{tr}(Z'W')] = \mathrm{tr}(ZW) -  N z w.
\end{equation}

To show that $\Phi$ is a left inverse of $\Psi$ we compute
\begin{equation}
\begin{aligned}
\Phi[\Psi[\mathcal{F}]](Z,W) &= \Psi[\mathcal{F}] \Big(Z - I \, \frac{\mathrm{tr}(Z)}{N}, W - I \, \frac{\mathrm{tr}(W)}{N} , 
\frac{\mathrm{tr}(Z)}{N} , \frac{\mathrm{tr}(W)}{N} \Big)
\\[1mm]
&= \mathcal{F} \Big( Z - I \, \frac{\mathrm{tr}(Z)}{N} + I \, \frac{\mathrm{tr}(Z)}{N} ,
W - I \, \frac{\mathrm{tr}(W)}{N} + I \, \frac{\mathrm{tr}(W)}{N} \Big) = \mathcal{F}(Z,W).
\end{aligned}
\end{equation}

To show that $\Phi$ is a right inverse of $\Psi$ we compute
\begin{equation}
\begin{aligned}
&\Psi[\Phi[\mathcal{F}' \otimes f]](Z',W',z,w) \\
&= \Phi[\mathcal{F}' \otimes f](Z'+Iz,W'+Iw)  \\
&= (\mathcal{F}' \otimes f) \Big(Z'+Iz-I \, \frac{\mathrm{tr} (Z'+Iz)}{N}, W'+Iw-I \, \frac{\mathrm{tr}(W'+Iw)}{N} , 
\frac{\mathrm{tr}(Z'+Iz)}{N}, \frac{\mathrm{tr}(W'+Iw)}{N} \Big) \\
&= (\mathcal{F}' \otimes f)(Z',W',z,w)
\end{aligned}
\end{equation}
where we used $\mathrm{tr} (X') = 0, \ \mathrm{tr}(I) = N$ and
\begin{equation}
\frac{\mathrm{tr}(X' + Ix)}{N} = \frac{\mathrm{tr}(X') + x \, \mathrm{tr} (I)}{N} = x, \qquad (X,x) \in \{  (Z,z),  (W,w) \}
\end{equation}
in the last equality.

For $(X,x) \in \{  (Z,z),  (W,w) \}$, we introduce projected traceless derivatives by
\begin{equation}
\mathcal L^{X'}_{ji} \equiv \pdv{}{X_{ij}}-\frac{\delta_{ij}}{N}\sum_{k=1}^N\pdv{}{X_{kk}} 
\label{def:proj-tr-der}
\end{equation}
which satisfy
\begin{equation}
\mathcal L^{X'}_{ji} ( x ) = 0, \qquad
\mathcal L^{X'}_{ji} ( X'_{kl} ) =\delta_{ik}\delta_{jl}-\frac{1}{N}\delta_{ij}\delta_{kl} \,.
\label{eq:proj-tr-der}
\end{equation}

In Lemma~\ref{lemma:oneloop factorisation} (see Appendix~\ref{app:trace factorisation}), we show that the one-loop dilatation operator can be rewritten using the projected traceless derivatives defined in \eqref{def:proj-tr-der}:
\begin{equation}
\mathfrak{D}_N^{\prime(1)} = -\frac{1}{N}:\mathrm{tr}\qty(\comm{Z'}{W'}\comm{\mathcal L^{Z'}}{\mathcal L^{W'}}): \,.
\label{eq: SUN deriv dil}
\end{equation}


As a consequence (Lemma \ref{lemma: weyl dil commute}), the one-loop dilatation operator commutes with $z,w, \pdv{z}, \pdv{w}$, where
\begin{equation}
    \pdv{x} = \sum_{i=1}^N \pdv{X_{ii}}, \quad (X,x) \in \{(Z,z),(W,w)\}.
\end{equation}
By Proposition~\ref{prop:hilb factorisation}, every invariant has a unique finite expansion
\begin{equation}
\mathcal{F}(Z,W)=\sum_{a,b\geq0}z^aw^b\mathcal{F}_{a,b}(Z',W'),
\end{equation}
and Lemma \ref{lemma: coefficient eigenspace factorisation} shows that $\mathfrak{D}_N^{(1)}\mathcal{F}=e\mathcal{F}$ holds if and only if
$\mathfrak{D}_N^{\prime(1)}\mathcal{F}_{a,b}=e\mathcal{F}_{a,b}$ for every $a,b \geq 0$.

The traceless invariant $\mathrm{tr}(Z'^2)$ is a half-BPS operator with $\mathfrak{D}_N^{\prime(1)}$ eigenvalue zero. The following operators
\begin{equation}
z^a w^b\mathrm{tr}(Z'^2) = z^a w^b \Big( \mathrm{tr} (ZZ) - N \, z^2 \Big), \qquad a,b\in\mathbb{Z}_{\geq 0}
\end{equation}
are $U(N)$ eigenstates with the same eigenvalue zero.

\label{lemma: dims eigenspaces relations}
The dimensions of fixed degree eigenspaces are related by
\begin{equation}
    \label{eq: m n e factorisation dim}
    \dim \mathcal{H}'_N(m,n,e) =
    \begin{aligned}[t]
    &\dim \mathcal{H}_N(m,n,e)
    +\dim \mathcal{H}_N(m-1,n-1,e) \\
    &-\dim \mathcal{H}_N(m-1,n,e)
    -\dim \mathcal{H}_N(m,n-1,e) \,.
    \end{aligned}
\end{equation}

Define the generating functions
\begin{equation}
    Z^{u(N)}_e (x,y) = \sum_{m,n \geq 0} x^m y^n \dim \mathcal{H}_N(m,n,e), \quad 
    Z^{su(N)}_e (x,y) = \sum_{m,n \geq 0} x^m y^n \dim \mathcal{H}'_N(m,n,e)\,.
\end{equation}
From Theorem \ref{prop:eigenspace factorisation} we have
\begin{equation}
    Z_e^{su(N)}(x,y) =  (1-x)(1-y)Z^{u(N)}_e(x,y) \,
\end{equation}
and extracting the coefficients of $x^{m}y^{n}$ gives the lemma.

\label{cor:suN charpoly}
The $SU(N)$ characteristic polynomials are computable in terms of $U(N)$ characteristic polynomials:
\begin{equation}
    \begin{aligned}
    \det_{\mathcal{H}_N'(m,n)}(x -  \mathfrak{D}^{\prime(1)}_N) 
    &=
    \frac{
    \det_{\mathcal{H}_N(m,n)}(x- \mathfrak{D}^{(1)}_N)
    \det_{\mathcal{H}_N(m-1,n-1)}(x- \mathfrak{D}^{(1)}_N)
    }
    {
    \det_{\mathcal{H}_N(m-1,n)}(x- \mathfrak{D}^{(1)}_N)
    \det_{\mathcal{H}_N(m,n-1)}(x- \mathfrak{D}^{(1)}_N)
    }
    \end{aligned}
\end{equation}
where we adopt the convention
\begin{equation}
{\mathcal H}_N(a,b)=0 \qquad {\rm and} \qquad
\det_{\mathcal H_N(a,b)} (x- \mathfrak{D}^{(1)}_N)=1 \qquad
{\rm if} \ a<0 \ {\rm or} \ b<0.
\end{equation}

Let $E$ be the union of the spectra of $\mathfrak{D}_N^{(1)}$ on the four spaces $\mathcal{H}_N(m,n)$, $\mathcal{H}_N(m-1,n-1)$, $\mathcal{H}_N(m-1,n)$ and $\mathcal{H}_N(m,n-1)$.
Lemma~\ref{lemma: dims eigenspaces relations} implies that $E$ contains the spectrum of $\mathfrak{D}_N^{\prime(1)}$ on $\mathcal{H}'_N(m,n)$.
The characteristic polynomial therefore factors over the real numbers as
\begin{equation}
    \det_{\mathcal{H}_N'(m,n)}(x -  \mathfrak{D}^{\prime(1)}_N) = \prod_{e \in E} (x-e)^{\dim \mathcal{H}'_N(m,n,e)} .
\end{equation}
From Lemma \ref{lemma: dims eigenspaces relations} we get
\begin{equation}
    \begin{aligned}
    \prod_{e \in E} (x-e)^{\dim \mathcal{H}'_N(m,n,e)}
    &=
    \prod_{e \in E} 
    \frac{
    (x-e)^{\dim \mathcal{H}_N(m,n,e)}
    (x-e)^{\dim \mathcal{H}_N(m-1,n-1,e)}
    }
    {
    (x-e)^{\dim \mathcal{H}_N(m-1,n,e)}
    (x-e)^{\dim \mathcal{H}_N(m,n-1,e)}
    } \\
    &=
    \frac{
    \det_{\mathcal{H}_N(m,n)}(x- \mathfrak{D}^{(1)}_N)
    \det_{\mathcal{H}_N(m-1,n-1)}(x- \mathfrak{D}^{(1)}_N)
    }
    {
    \det_{\mathcal{H}_N(m-1,n)}(x- \mathfrak{D}^{(1)}_N)
    \det_{\mathcal{H}_N(m,n-1)}(x- \mathfrak{D}^{(1)}_N) 
    } \,.
    \end{aligned}
\end{equation}
In particular, for any $e\in E$ absent from the spectrum of $\mathcal{H}_N'(m,n)$, Lemma~\ref{lemma: dims eigenspaces relations} ensures that the corresponding factors cancel between the numerator and denominator.

\label{prop:HWS dim comp}
The dimensions of highest-weight eigenspaces are related by
\begin{equation}
    \dim \mathcal{H}_N'^{\mathrm{HWS}}(m,n,e) = 
    \begin{aligned}[t]
        &\dim \mathcal{H}_N^{\mathrm{HWS}}(m,n,e) -
        (1-\delta_{m,n})\dim \mathcal{H}_N^{\mathrm{HWS}}(m-1,n,e) \\
        &-\dim \mathcal{H}_N^{\mathrm{HWS}}(m,n-1,e)+
        \dim \mathcal{H}_N^{\mathrm{HWS}}(m-1,n-1,e)
    \end{aligned}
\end{equation}
where the factor $1-\delta_{m,n}$ removes the $(m-1,m)$ term, which is not a valid partition.

Expanding the generating functions in terms of irreducible characters of $U(2)$ gives
\begin{equation}
    \sum_{L=0}^\infty \sum_{\substack{\Lambda \vdash L \\ \ell(\Lambda) \leq 2}} m^{su(N),e}_\Lambda \chi^\Lambda(x,y) = (1-x)(1-y)\sum_{L=0}^\infty \sum_{\substack{\Lambda \vdash L \\ \ell(\Lambda) \leq 2}} m^{u(N),e}_\Lambda \chi^\Lambda(x,y) .
    \label{eq: cor proof Z fixed e1}
\end{equation}
Here $m^{u(N),e}_\Lambda$ and $m^{su(N),e}_\Lambda$ are the multiplicities of the representation $\Lambda$ in $\mathcal{H}_N(e)$ and $\mathcal{H}'_N(e)$, respectively, and
\begin{equation}
\chi^{\Lambda } ( x , y ) = \frac{x^{\lambda_1+1} y^{\lambda_2} - x^{\lambda_2} y^{\lambda_1+1}}{x-y} \,.
\label{def:U2 char}
\end{equation}
Now use the fact that
\begin{equation}
    (1-x)(1-y) = 1 - \chi^{[1]}(x,y) + \chi^{[1,1]}(x,y) 
\end{equation}
and Pieri's formula which gives
\begin{equation}
    \begin{aligned}
    \chi^{[1]}(x,y)\chi^{[\lambda_1,\lambda_2]}(x,y) &= 
    \chi^{[\lambda_1+1,\lambda_2]}(x,y) + 
    \chi^{[\lambda_1,\lambda_2+1]}(x,y), \\
    \chi^{[1,1]}(x,y)\chi^{[\lambda_1,\lambda_2]}(x,y) &= 
    \chi^{[\lambda_1+1,\lambda_2+1]}(x,y)\,
    \end{aligned}
\end{equation}
where a character vanishes, by definition, if $\lambda_2 > \lambda_1$.
Substituting this into \eqref{eq: cor proof Z fixed e1} with $\Lambda=[\lambda_1,\lambda_2]$, and suppressing the $x,y$ dependence, gives
\begin{equation}
\sum_{L=0}^\infty \sum_{\substack{\Lambda \vdash L \\ \ell(\Lambda) \leq 2}} m^{su(N),e}_\Lambda \chi^\Lambda 
= \sum_{L=0}^\infty \sum_{\substack{\Lambda \vdash L \\ \ell(\Lambda) \leq 2}} 
m^{u(N),e}_{[\lambda_1,\lambda_2]} \, \Big( 
\chi^{[\lambda_1,\lambda_2]} - \chi^{[\lambda_1+1,\lambda_2]} - \chi^{[\lambda_1,\lambda_2+1]} + \chi^{[\lambda_1+1,\lambda_2+1]} 
\Big) .
\end{equation}
Here multiplicities with negative entries or entries that do not form a partition are understood to vanish.
Comparing the coefficients of $\chi^\Lambda$ gives
\begin{equation}
    m^{su(N),e}_{[\lambda_1,\lambda_2]} = 
    m^{u(N),e}_{[\lambda_1,\lambda_2]} -
    (1-\delta_{\lambda_1,\lambda_2})m^{u(N),e}_{[\lambda_1-1,\lambda_2]} -
    m^{u(N),e}_{[\lambda_1,\lambda_2-1]} +
    m^{u(N),e}_{[\lambda_1-1,\lambda_2-1]} \, .
\end{equation}
Since each irreducible representation associated with $\Lambda$ has a one-dimensional highest-weight subspace, the multiplicity of the character $\chi^\Lambda$ is equal to the dimension of the highest-weight space.
In other words, we can identify
\begin{equation}
    m^{su(N),e}_{[m,n]} = 
    \dim \mathcal{H}_N'^{\mathrm{HWS}}(m,n,e), \quad 
    m^{u(N),e}_{[m,n]} =
    \dim \mathcal{H}_N^{\mathrm{HWS}}(m,n,e).
\end{equation}

A permutation $g \in S_{m+n}$ is called a derangement if it has no fixed points. The subset
\begin{equation}
D_{m+n} = \{ g \in S_{m+n} \, \vert \, g(i) \neq i \quad \forall i \in \{1,\dots,m+n\} \}
\end{equation}
is called the set of derangements in $S_{m+n}$\,. 
Note that $D_{m+n}$ does not form a subgroup, since it does not contain the identity permutation.

The DOS ${\mathcal D}(2,2)$ has dimension $r = 4$. A complete set of representatives is
    \begin{equation}
        \begin{aligned}
            &&g_1 = (12)(34),   \,
            &&g_2 = (13)(24),   \,
            &&g_3 = (1234),     \,
            &&g_{4} = (1324)\, .
        \end{aligned}
        \label{eq: cD22 orbits}
    \end{equation}
    This should be compared to ${\mathcal A}(2,2)$ in Example \ref{ex:cA22} which has dimension ten.
    A subset of its orbit basis elements corresponds to Equation \eqref{eq: cD22 orbits}.

\label{eq:Osigma-traceless-definition}
    Let $g\in D_{m+n}$ and fix $m,n \in \mathbb{Z}_{\geq 0}$ and $N\geq 1$, with $L=m+n$. Define the multi-trace invariant
\begin{equation}
    \begin{aligned}
    &\mathscr{O}'^{(N)}_{m,n}: {\mathcal D}(m,n) \rightarrow \mathcal{H}'_N(m,n)\\
    &\mathscr{O}'^{(N)}_{m,n}(g)
\equiv
\sum_{i_1,\dots,i_L=1}^N
\prod_{p=1}^m Z'_{i_p i_{g(p)}}
\prod_{q=m+1}^L W'_{i_q i_{g(q)}} \,.
    \end{aligned}
\end{equation}
For an element $\sigma=\sum_{g\in D_{m+n}}c_g(\sigma)g \in {\mathcal D}(m,n)$ we linearly extend the above map,
\begin{equation}
    \mathscr{O}'^{(N)}_{m,n}(\sigma)
\equiv
\sum_{g\in D_{m+n}}c_g(\sigma)\,\mathscr{O}'^{(N)}_{m,n}(g)
\end{equation}
where $c_g(\sigma) \in \mathbb{C}$.

We give a simple argument based on counting using the inclusion-exclusion principle.
Note that $\dim {\mathcal D}(m,n)$ is equal to the number of orbit basis elements of ${\mathcal A}(m,n)$ with no fixed points.
The number of orbit basis elements of ${\mathcal A}(m,n)$ with at least one fixed point in $\{1,\dots,m\}$ is given by $\dim {\mathcal A}(m-1,n)$.
Similarly the number of orbits with at least one fixed point in $\{m+1,\dots,m+n\}$ is given by $\dim {\mathcal A}(m,n-1)$.
However, this overcounts by the overlap -- the orbits of permutations with at least one fixed point in each set -- which have cardinality $\dim {\mathcal A}(m-1,n-1)$.
The inclusion-exclusion principle gives
\begin{equation}
    \dim {\mathcal D}(m,n) = \dim {\mathcal A}(m,n) - \dim {\mathcal A}(m,n-1) - \dim {\mathcal A}(m-1,n) + \dim {\mathcal A}(m-1,n-1) \,.
\end{equation}
For $N \geq m+n$ we have $\dim {\mathcal A}(m,n) = \dim \mathcal{H}_N(m,n)$ and together with the factorisation in Proposition~\ref{prop:hilb factorisation} we get
\begin{equation}
    \begin{aligned}
        \dim {\mathcal D}(m,n) &=
        \dim {\mathcal H}_N(m,n) - \dim {\mathcal H}_N(m,n-1) - \dim {\mathcal H}_N(m-1,n) + \dim {\mathcal H}_N(m-1,n-1) \\
        &= \dim {\mathcal H}_N'(m,n) \,.
    \end{aligned}
\end{equation}
Since the map is surjective and the dimensions agree, the kernel is trivial.

\label{def:orbit-basis inner prod DOS}
The orbit-basis inner product in ${\mathcal D}(m,n)$ is given by
\begin{equation}
\langle \sigma, \sigma' \rangle = \delta(\sigma {\mathcal S}(\sigma')) .
\label{eq: inner prod DOS}
\end{equation}
The Gram matrix in the orbit basis for ${\mathcal D}(m,n)$ is defined by
\begin{equation}
    ( {G}_{\mathrm{dos}} (m,n) )_{pq} = \langle P_{m,n}(g_p) , P_{m,n}(g_q) \rangle , \qquad (p, q \in \{ 1, \dots, \dim {\mathcal D}(m,n) \}).
\label{eq: Gram matrix orbit-DOS}
\end{equation}

\label{lemma:oneloop factorisation}
The derivatives in the one-loop dilatation operator on $\mathcal{H}_N$ can be replaced with projected traceless derivatives
\begin{equation}
\mathfrak{D}^{(1)}_N
= -\frac{1}{N}:\mathrm{tr} \qty(\comm{Z}{W} \comm{\pdv{}{Z}}{\pdv{}{W}}): \ \ 
= -\frac{1}{N}:\mathrm{tr} \qty(\comm{Z'}{W'} \comm{ \mathcal L^{Z'} }{ \mathcal L^{W'} }): \,.
\end{equation}

Consider the first commutator
    \begin{equation}
        \comm{Z}{W}_{ij} = \comm{(Z'+zI)}{(W'+wI)}_{ij} = \comm{Z'}{W'}_{ij}
    \end{equation}
    the last equality uses the fact that the identity matrix commutes with all matrices.
    For the second commutator
\begin{equation}
\comm{\pdv{}{Z}}{\pdv{}{W}}_{ij} 
= \comm{ \Big( \mathcal L^{Z'} + \frac{I}{N}\pdv{}{z} \Big) }{ \Big( \mathcal L^{W'} + \frac{I}{N}\pdv{}{w} \Big)}_{ij}
\end{equation}
    all but the first term vanish: 
\begin{align}
\comm{ \mathcal L^{Z'} }{\frac{I}{N}\pdv{w}}_{ij}
&=\sum_{k=1}^N \qty( \mathcal L^{Z'}_{ik} \, \frac{\delta_{kj}}{N} \pdv{}{w} - \frac{\delta_{ik}}{N}\pdv{}{w} \mathcal L^{Z'}_{kj} ) 
= \frac{1}{N} \qty( \mathcal L^{Z'}_{ij} \pdv{}{w} - \pdv{}{w} \mathcal L^{Z'}_{ij} ) =0 , \\
\comm{\frac{I}{N}\pdv{z}}{ \mathcal L^{W'} }_{ij}
&=\sum_{k=1}^N \qty(\frac{\delta_{ik}}{N} \pdv{}{z} \mathcal L^{W'}_{kj} - \mathcal L^{W'}_{ik} \frac{\delta_{kj}}{N}\pdv{}{z}) 
= \frac{1}{N} \qty(\pdv{z} \mathcal L^{W'}_{ij} - \mathcal L^{W'}_{ij} \pdv{}{z} ) =0 , \\
\comm{\frac{I}{N}\pdv{z}}{\frac{I}{N}\pdv{w}}_{ij}
&=\sum_{k=1}^N \qty(\frac{\delta_{ik}}{N} \pdv{z} \frac{\delta_{kj}}{N} \pdv{w} -\frac{\delta_{ik}}{N} \pdv{w} \frac{\delta_{kj}}{N} \pdv{z} ) 
= \frac{1}{N^2} \delta_{ij} \qty(\pdv{z}\pdv{w} - \pdv{w}\pdv{z}) = 0.
\end{align}

\label{def:single-letter-trace-counting}
Define the single-letter-trace counting operators by
\begin{equation}
\hat{\mathcal{N}}^{(s)} \equiv \hat{\mathcal{N}}^{(s)}_z + \hat{\mathcal{N}}^{(s)}_w , \qquad
\hat{\mathcal{N}}^{(s)}_x \equiv \frac{1}{N} \sum_{a,b=1}^N X_{aa} \, \frac{\partial}{\partial X_{bb}} = x \frac{\partial}{\partial x} \,.
\label{def:slcnt}
\end{equation}
The equality follows from \eqref{def:sl-trace} and \eqref{eq:sl-deriv}. 
The operators $\hat{\mathcal{N}}^{(s)}_z$ and $\hat{\mathcal{N}}^{(s)}_w$ count the degrees in $z$ and $w$ at fixed $Z'$ and $W'$, respectively.

\label{lemma: weyl dil commute}
    The one-loop dilatation operator commutes with the operators $x, \pdv{x}$ and $\hat{\mathcal{N}}^{(s)}_{x}$ 
\begin{equation}
    \comm{ \mathfrak{D}^{(1)}_{N}}{\hat{\mathcal{N}}^{(s)}_x} =
    \comm{ \mathfrak{D}^{(1)}_{N}}{x} =
    \comm{ \mathfrak{D}^{(1)}_{N}}{\pdv{x}} =
     0 \,,
\end{equation}
where $x \in \{z,w\}$.

Since $\mathcal{F}(Z,W) \in {\mathcal H}_N$ has a finite expansion into elements of $\mathcal{H}'_N \otimes \mathbb{C}[z,w]$,
\begin{equation}
    \label{eq: exp Fe}
    \mathcal{F}(Z,W) = \sum_{a,b = 0}^\infty \mathcal{F}_{a,b}(Z',W')z^a w^b,
\end{equation}
it suffices to prove this for polynomials of the form $\mathcal{F}'(Z',W')z^a w^b$. 
The substitution maps are omitted below to simplify the notation.

First, for $(X,x) \in \{(Z,z),(W,w)\}$, the traceless derivatives satisfy \eqref{eq: traceless D on trace}:
\begin{equation}
   \label{eq:traceless deriv orthogonality}
\mathcal L^{X'}_{ji} ( x ) =  0 \, .
\end{equation}
It follows that for $\mathcal{F}'(Z',W') \in {\mathcal H}_N'$
\begin{equation}
   \mathcal L^{X'}_{ji}  \qty( z^{a} w^{b}\mathcal{F}'(Z',W') ) =
   z^{a}w^{b}
   \mathcal L^{X'}_{ji} \Big( \mathcal{F}'(Z',W') \Big),  \quad \forall a,b \in \mathbb{Z}_{\geq 0} \,
\end{equation}
and using Lemma \ref{lemma:oneloop factorisation}
\begin{equation}
    \comm{ \mathfrak{D}^{(1)}_{N}}{x} =  0 \,.
\end{equation}
Secondly, using 
\begin{equation}
\label{eq: trace deriv orthogonality}
\pdv{}{x} X'_{ij} = \sum_{k=1}^N \pdv{}{X_{kk}}   \qty(X_{ij} - \delta_{ij}x) = \sum_{k=1}^N \qty(\delta_{ki} \delta_{kj} - \frac{\delta_{ij}}{N}) = 0
\end{equation}
we have
\begin{equation}
\begin{aligned}
 \mathfrak{D}^{(1)}_N \pdv[c]{z} \pdv[d]{w} \mathcal{F}'(Z',W')z^a w^b 
&=\Big\{  \mathfrak{D}^{\prime(1)}_N \mathcal{F}'(Z',W') \Big\} \, \Big\{ \pdv[c]{z} \pdv[d]{w} z^{a} w^b \Big\} \\
&=\pdv[c]{z} \pdv[d]{w} \,  \mathfrak{D}^{(1)}_N \mathcal{F}'(Z',W')z^a w^b  
\quad \forall c,d \in \mathbb{Z}_{\geq 0}.
\end{aligned}
\end{equation}
Combining the two results we get
\begin{equation}
    \comm{ \mathfrak{D}^{(1)}_{N}}{\hat{\mathcal{N}}^{(s)}_x} = 0 \,.
\end{equation}

\label{lemma: coefficient eigenspace factorisation}
    Let $\mathcal{F}^{(e)}(Z,W) \in \mathcal{H}_N$ be a non-zero polynomial with expansion
\begin{equation}
\mathcal{F}^{(e)}(Z,W) = \sum_{a,b = 0}^\infty \mathcal{F}^{(e)}_{a,b}(Z',W')z^a w^b.
\label{eq: exp Fe2}
\end{equation}
This is an eigenvector with eigenvalue $e$ if and only if every nonzero coefficient $\mathcal{F}^{(e)}_{a,b}(Z',W')$ is an eigenvector with eigenvalue $e$.
    \begin{equation}
        \mathfrak{D}^{(1)}_N \mathcal{F}^{(e)}(Z,W) =e \mathcal{F}^{(e)}(Z,W) 
        \Longleftrightarrow 
        \mathfrak{D}^{\prime(1)}_N \mathcal{F}^{(e)}_{a,b}(Z',W') =e \mathcal{F}^{(e)}_{a,b}(Z',W') , \quad \forall a,b \geq 0.
    \end{equation}

The easy direction assumes $\mathcal{F}^{(e)}_{a,b}(Z',W') \in \mathcal{H}'_N(e)$ are eigenvectors of the dilatation operator with eigenvalue $e$
\begin{equation}
    \mathfrak{D}^{\prime(1)}_N \mathcal{F}_{a,b}^{(e)}(Z',W') = e \mathcal{F}_{a,b}^{(e)}(Z',W'), \quad \forall a,b \geq 0.
\end{equation}
Lemma \ref{lemma: weyl dil commute} gives 
\begin{equation}
    \mathfrak{D}^{(1)}_N \qty(z^{a}w^{b}\mathcal{F}_{a,b}^{(e)}(Z',W')) 
    = z^{a}w^{b} \,  \mathfrak{D}^{\prime(1)}_N \mathcal{F}_{a,b}^{(e)}(Z',W')
    = e z^{a}w^{b}\mathcal{F}^{(e)}_{a,b}(Z',W').
\end{equation}
By linearity, we get that $\mathcal{F}^{(e)}(Z,W)$ is an eigenvector with eigenvalue $e$.

For the other direction, we assume $\mathcal{F}^{(e)}(Z,W) \in \mathcal{H}_N(e)$ and deduce that $\mathcal{F}^{(e)}_{a,b}(Z',W') \in \mathcal{H}'_N(e)$.
For this, note that the single-letter-trace counting operators 
have non-negative integer eigenvalues as operators on $\mathcal{H}_N$
\begin{equation}
    \mathrm{Spectrum}(\hat{\mathcal{N}}^{(s)}_x) = \{0,1,2,\dots \}.
\end{equation}
They can be used to construct maps extracting the coefficients $\mathcal{F}^{(e)}_{a,b}(Z',W')$.
By assumption, $\mathcal{F}^{(e)}(Z,W)$ has bounded degree and so $\mathcal{F}^{(e)}_{a,b}(Z',W')$ all vanish for some finite upper limits $a > A, b > B$.
Using this, we define
\begin{equation}
\mathrm{Coeff}_z(a) = \frac{1}{a!}\pdv[a]{z}\prod_{\substack{c=0\\c \neq a}}^A \frac{\hat{\mathcal{N}}^{(s)}_z-c}{a-c}, \qquad
\mathrm{Coeff}_w(b) =\frac{1}{b!}\pdv[b]{w} \prod_{\substack{d=0\\d \neq b}}^B \frac{\hat{\mathcal{N}}^{(s)}_w-d}{b-d} \,.
\end{equation}
They satisfy 
\begin{equation}
\mathrm{Coeff}_z(a) \, \mathrm{Coeff}_w(b)\qty(\mathcal{F}^{(e)}(Z,W)) = \mathcal{F}^{(e)}_{a,b}(Z',W') \,,
\end{equation}
and commute with the dilatation operator since they are polynomials in $\hat{\mathcal{N}}^{(s)}_x, \pdv{x}$.
A short computation gives 
\begin{equation}
    \begin{aligned}
     \mathfrak{D}^{\prime(1)}_N \mathcal{F}^{(e)}_{a,b} (Z',W')
    &= \mathfrak{D}^{(1)}_N \qty[\mathrm{Coeff}_z(a) \, \mathrm{Coeff}_w(b) \, \mathcal{F}^{(e)}(Z,W) ] \\
    &= \mathrm{Coeff}_z(a) \, \mathrm{Coeff}_w(b) \, \mathfrak{D}^{(1)}_N \mathcal{F}^{(e)}(Z,W) \\
    &= \mathrm{Coeff}_z(a) \, \mathrm{Coeff}_w(b) \, e\mathcal{F}^{(e)}(Z,W) \\
    &= e \mathcal{F}^{(e)}_{a,b}(Z',W').
    \end{aligned}
\end{equation}

\label{app:single-letter-trace SL}

The single-letter-trace counting operators \eqref{def:slcnt} have a permutation description. Their action on the $U(N)$-invariant operators $\mathscr{O}^{(N)}_{m,n}(g)$ for $g \in S_L$ can be computed in a similar way to Appendix \ref{app:induced action D1} as
\begin{equation}
\hat{\mathcal{N}}^{(s)}_z \cdot \mathscr{O}^{(N)}_{m,n}(g) = \frac{1}{N} \sum_{p=1}^m \mathscr{O}^{(N)}_{m,n} \bigl(g\,\llbracket p,g(p) \rrbracket\bigr) , \qquad
\hat{\mathcal{N}}^{(s)}_w \cdot \mathscr{O}^{(N)}_{m,n}(g) = \frac{1}{N} \sum_{q=m+1}^{L} \mathscr{O}^{(N)}_{m,n} \bigl(g\,\llbracket q,g(q) \rrbracket\bigr) .
\end{equation}
These identities extend linearly to $\mathbb{C}[S_L]$. 
The total single-letter-trace counting operator satisfies the following intertwining relation similar to \eqref{eq:intertwine},
\begin{equation}
\hat{\mathcal{N}}^{(s)} \cdot \mathscr{O}^{(N)}_{m,n}(g) = \mathscr{O}^{(N)}_{m,n} \Bigl( \mathcal{N}^{(s)}_{\xi} (g) \Bigr) \Big|_{\xi = 1/N} \,, \qquad
\mathcal{N}^{(s)}_{\xi} (g) = 
{\sf Fix} (g) \, g + \xi \sum_{\substack{i=1\\ i\ne g(i)}}^L g (i,g(i)) 
\label{app:Ns induced SL}
\end{equation}
where ${\sf Fix} (g)$ counts the number of fixed points in $g$.

On a polynomial $\mathcal{F}'(Z',W')z^a w^b$, the operator $\hat{\mathcal{N}}^{(s)}$ has eigenvalue $(a+b)$. 
The intertwining relation \eqref{app:Ns induced SL} implies that the permutation operator $\mathcal{N}^{(s)}_{\xi}$ preserves $\ker\mathscr{O}^{(N)}_{m,n}$ at $\xi=1/N$.
The block-triangular argument used in Lemma \ref{cor:finite-N factorisation} gives
\begin{equation}
\left.\det_{{\mathcal A}(m,n)}(x-\mathcal{N}^{(s)}_{\xi})\right|_{\xi=1/N}=Q^{(s,N)}_{m,n}(x)\det_{\mathcal{H}_N(m,n)}(x-\hat{\mathcal{N}}^{(s)}),
\end{equation}
where $Q^{(s,N)}_{m,n}(x)$ is the characteristic polynomial in the null sector.

Let $g_i,g_j \in D_{m+n}$ be a pair of derangements. Define the derangement $g_i \otimes g_j \in D_{2m+2n}$ as
    \begin{equation}
        g_i \otimes g_j = g_i \prod_{l=1}^{m+n} (l,l+m+n)g_j\prod_{l=1}^{m+n} (l,l+m+n)\,.
    \end{equation}
    In other words, it is the derangement where $g_i$ is viewed as a permutation of $\{1,\dots,m+n\}$ while $g_j$ is viewed as a permutation of the numbers $\{m+n+1,\dots, 2m+2n\}$
    The number of cycles in a permutation $g$ is denoted $\mathrm{cycles}(g)$.
    The Wick contractions in the inner product are encoded in a sum over $S_m \times S_n$ and a sum over subsets $S \subseteq \{1,\dots,m+n\}$ which correspond to the choice of the first or second term in \eqref{eq:suN wick} for each contraction,
    \begin{equation}
        \begin{aligned}
            \langle \mathscr{O}'^{(N)}_{m,n}(g_i)(Z',W') &\mathscr{O}'^{(N)}_{m,n}(g_j^{-1})(Z'^\dagger,W'^\dagger) \rangle_{SU(N)} = \\
            &\sum_{\substack{h \in S_m \times S_n \\
            S \subseteq \{1,\dots,m+n\}}} (-N)^{\vert S \vert-m-n}
            N^{\mathrm{cycles}([\prod_{l \in S} (l,m+n+l)][(h g_i h^{-1}) \otimes g_j^{-1}])} 
        \end{aligned}
    \label{app:SUN-2pt der}
    \end{equation}
which generalises the free two-point function of the $U(N)$ gauge theory \eqref{eq: U(N) inner prod}.

